package main

import "testing"

func TestValidNumber(t *testing.T) {
	if !Valid("4539148803436467") {
		t.Error("expected a Luhn-valid number to be valid")
	}
}

func TestOneDigitOff(t *testing.T) {
	if Valid("4539148803436466") {
		t.Error("a number with a bad check digit must be invalid")
	}
}

func TestEmpty(t *testing.T) {
	if Valid("") {
		t.Error("empty string must be invalid")
	}
}

func TestNonDigit(t *testing.T) {
	if Valid("45391488034364z7") {
		t.Error("a non-digit character must make it invalid")
	}
}

